PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?album (COALESCE(?dbpDate, ?dboDate) AS ?releaseDate) WHERE {
  VALUES ?album { dbr:Issa_Album dbr:3.2.1. }
  OPTIONAL { ?album dbp:released ?dbpDate . }
  OPTIONAL { ?album dbo:releaseDate ?dboDate . }
}
LIMIT 100

